  Notation SP' := (Z_to_bv 64 (bv_unsigned sp + -176)).
  Notation SB := (Z_to_bv 64 (al_sb AL)).
  Notation SHB := (Z_to_bv 64 (Z.shiftr B 3 + al_sb AL)).
  Notation FRAME mm := (rw_cells asegs mm (bv_unsigned sp + -176)
     [CB 8 j0; C8 wbd; C8 (Z_to_bv 64 X); C8 (Z_to_bv 64 (al_sb AL + Z.shiftr B 3)); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 1); C8 (Z_to_bv 64 1);
      C8 (Z_to_bv 64 bn); C8 wmm;
      C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]).
  Notation OBJS mm := (aobj asegs AL CS mm X (4 * an) /\ aobj asegs AL CS mm A (4 * an) /\ aobj asegs AL CS mm B (4 * bn)
                       /\ aobj asegs AL CS mm N (4 * an) /\ aobj asegs AL CS mm T (4 * (2 * an + 1))).
  (* [comment removed for export] *)
  Notation TT := (skipn (Z.to_nat (2 * an + 1)) ts0).
  Notation TINV WW mm ts := (u32arr asegs mm T ts /\ Z.of_nat (length ts) = 2 * an + 1 /\ u32arr asegs mm (T + 4 * (2 * an + 1)) TT
                          /\ munch WW m mm /\ wmono asegs m mm /\ mem_inv asegs mm /\ stk asegs mm lo (bv_unsigned sp + -176)
                          /\ HM asegs R HIA h LB LF mm /\ OBJS mm).
  Notation SUMS := [SUM_amemsetWA 4 5; SUM_mlawA 4].   (* [comment removed for export] *)

  Lemma sub_W1_W : sub_fp W1 W.
  Proof. intros x Hx. cbn [outside] in *. clear -Hx. tauto. Qed.

