  Lemma tail_walk : forall (xs ts : list word) (mm : mem)
      (xra xt0 xt1 xt2 xs1 xa0 xa2 xa3 xa5 xa6 xa7 xs2 xs3 xs4 xs5 xs6 xs7 xs8 xs9 xs10 xs11 xt3 xt4 xt5 xt6 : word)
