  intros until ts. intros HH HX HA HB HN HT Han Hbn LX LA LZS LN LT DXT DAT DBT DNT DNX ALX ALA ALB ALN ALT NZX NZA NZB NZN NZT XT AT BT NT TT
         ST LOS LO TOP SPA SX SA SB SN STT CWX CWT MI RA OX OA OB ON OT -> -> -> -> -> -> ->.
  unfold MPI_CORE_MONTMUL_STACK_A in *.
  pose (lxi := lxA_img (arl_AL R) IMG).
  pose proof (hcs_ok asegs R HIA h) as CSOK. pose proof (cs_ok_sb _ _ CSOK) as SB64.
  pose proof (art_alwf asegs R HIA) as ALWF'. unfold al_wf in ALWF'. pose proof IMG as IMG'. unfold asan_img_ok in IMG'.
  pose proof (art_lo asegs R HIA) as ALO. pose proof (alloc_ceiling_pos (L := arl_L R)) as ACP.
  pose proof (hcs_stack asegs R HIA h) as SCS0. pose proof (hm_top asegs R HIA h LB LF m HH) as HTOP.
  pose proof (u32arr_bound _ _ _ _ HX) as XB0. pose proof (u32arr_bound _ _ _ _ HT) as TB0.
  pose proof (u32ro_bound _ _ _ _ HA) as AB0. pose proof (u32ro_bound _ _ _ _ HB) as BB0. pose proof (u32ro_bound _ _ _ _ HN) as NB0.
  pose proof (bv_unsigned_in_range 64 sp) as SPR. unfold bv_modulus in SPR.
  assert (LO0 : 0 <= lo) by klia.
  assert (SCS : crange (hcs asegs R HIA h) lo (bv_unsigned sp - lo)) by (eapply crange_sub; [exact SCS0| klia| klia]).
  pose proof (munch_refl [(T, T + 4 * (2 * an + 1)); (lo, bv_unsigned sp)] m) as MU.
  pose proof (wmono_refl asegs m) as WM.
  pose proof (lock HX) as HX0. pose proof (lock HA) as HA0. pose proof (lock HB) as HB0. pose proof (lock HN) as HN0.
  (* [comment removed for export] *)
  clear HA HB HN.
  apply lock in DAT. apply lock in DBT. apply lock in DNT. apply lock in DNX. apply lock in SA. apply lock in SB. apply lock in SN.
  pose proof (hm_abase asegs R HIA h LB LF m HH) as ABS.
  (* [comment removed for export] *)
  pose proof (firstn_skipn (Z.to_nat (2 * an + 1)) ts) as EY. symmetry in EY.
  assert (LP : Z.of_nat (length (firstn (Z.to_nat (2 * an + 1)) ts)) = 2 * an + 1) by (rewrite firstn_length; klia).
  rewrite EY in HT. apply u32arr_app in HT. destruct HT as [HTB HTC].
  replace (T + 4 * Z.of_nat (length (firstn (Z.to_nat (2 * an + 1)) ts))) with (T + 4 * (2 * an + 1)) in HTC by (clear - LP; lia).
  assert (LTL : Z.of_nat (length (skipn (Z.to_nat (2 * an + 1)) ts)) = Z.of_nat (length ts) - (2 * an + 1)) by (rewrite skipn_length; klia).
  clear EY.
  carve_frame 176%nat ST.
  apply (rw_cells_split_CB _ _ _ [] 176%nat junk [] [8%nat; 168%nat]) in FR; [| reflexivity]. cbn [app mk_CB_cells] in FR.
  clear HX.
  (* [comment removed for export] *)
  lx_pre. lxr_pose. lxm_sums [SUM_amemsetWA 4 5; SUM_mlawA 4] [T; 2 * an + 1].
  lx_pre. lx_run_tac (PLANS [0xa5578] [] 90%N [SUM_amemsetWA 4 5; SUM_mlawA 4]). lx_tree.
  all: lxr_leaf.
  match goal with K : aobj _ _ _ ?m2 T ?n8 |- evtA _ _ _ _ (MS _ _ _ _ _ ?m2 _) => replace n8 with (4 * (2 * an + 1)) in K by (clear; lia); rename K into OT' end.
  match goal with K : u32arr asegs ?m2 (T + ?d) _ |- evtA _ _ _ _ (MS _ _ _ _ _ ?m2 _) => replace (T + d) with (T + 4 * (2 * an + 1)) in K by (clear; lia); rename K into HTL' end.
  match goal with K : munch [(T, T + ?d); _] m ?m2 |- evtA _ _ _ _ (MS _ _ _ _ _ ?m2 _) => replace (T + d) with (T + 4 * (2 * an + 1)) in K by (clear; lia); rename K into MU' end.
  lazymatch goal with |- evtA _ _ _ _ (MS _ _ _ _ _ ?m2 _) =>
    match goal with H1 : u32arr asegs m2 T ?l, HL : Z.of_nat (length ?l) = _, H4 : mem_inv asegs m2, H5 : stk asegs m2 lo _, H6 : HM _ _ _ h LB LF m2, WM' : wmono _ m m2,
                     O1 : aobj _ _ _ m2 X _, O2 : aobj _ _ _ m2 A _, O3 : aobj _ _ _ m2 B _, O4 : aobj _ _ _ m2 N _ |- _ =>
      assert (LT1 : Z.of_nat (length l) = 2 * an + 1) by (rewrite HL; exact LP);
      pose proof (conj H1 (conj LT1 (conj HTL' (conj MU' (conj WM' (conj H4 (conj H5 (conj H6 (conj O1 (conj O2 (conj O3 (conj O4 OT')))))))))))) as TI end end.
  eapply (@loop_walk) with (k := Z.to_nat an) (i := 0) (lx := Z.of_nat (length xs)) (la := Z.of_nat (length ys)) (lb := Z.of_nat (length zs))
      (ln := Z.of_nat (length ns)) (lt := Z.of_nat (length ts)) (ys := ys) (zs := zs) (ns := ns) (xs0 := xs) (ts0 := ts);
    try eassumption; try reflexivity; try klia; try (f_equal; klia).
  all: try exact (unlock _ HX0). all: try exact (unlock _ HA0). all: try exact (unlock _ HB0). all: try exact (unlock _ HN0).
  all: match goal with |- ?g => idtac "MAIN-LEFT:" g end.
Qed.
